const AJUDA_GERAL = [
  ['Testes: Causa e Efeito', '<p>Rola-se <b>2d12</b>: o 1.º é <b>Causa</b>, o 2.º é <b>Efeito</b>. O sucesso depende da <b>soma</b> + atributo vs. dificuldade. Se Causa &gt; Efeito: sucesso ou falha <i>com Causa</i> (ganhas Causas). Se Causa &lt; Efeito: sucesso ou falha <i>com Efeito</i> (o Mestre ganha Efeitos, até 12).</p><p>Dados iguais = <b>crítico</b>: ganhas 1 Causa e 1 PI.</p><p>Dificuldades: 5 muito fácil · 10 fácil · 15 média · 20 difícil · 25 muito difícil · 30 quase impossível.</p>'],
  ['Vantagem e Desvantagem', '<p>Jogadores rolam um <b>d6</b> extra que soma (Vantagem) ou subtrai (Desvantagem). O Mestre rola 2d20 e fica com o maior ou o menor.</p>'],
  ['Dano e Limites', '<p>O dano é <b>Menor</b>, <b>Grave</b> ou <b>Severo</b> conforme os Limites de Dano da armadura. Dano físico é de armas; dano frásico vem sobretudo de Palavras.</p><p>Ao ficares sem PV e PI fazes a <b>Ação do Destino</b>.</p>'],
  ['Descansos', '<p><b>Curto</b> (escolhe 2 ações, o Mestre ganha 1d4 Efeito): Tratar de Feridas (1d4+Rank PV e remove Condição) · Revisa o Conhecimento (1d4+Rank PI) · Repara Armadura (1d4+Rank) · Prepara-te (+1 Causa; com equipa, cada um 2).</p><p><b>Longo</b> (escolhe 2): Tratar de Todas as Feridas · Reflete Todo o Conhecimento · Recupera Toda Armadura · Prepara-te · Dedica-te ao Treinamento (+1 PE) · Trabalha num Projeto · Repouso (remove Exaustão).</p>'],
  ['Deslocamento e Distâncias', '<p>Deslocamento base <b>4</b> (6 m). Adjacente 1,5 m · Curto 3 m · Médio 6 m · Longo 12 m · Distante 24 m · Longínquo 30 m.</p>'],
  ['Exaustão e Sorte', '<p>Cada nível de Exaustão dá <b>-2</b> nos testes; ao nível 5 fazes a Ação do Destino. Se tiveres de perder uma Causa e não tiveres, recebes um nível. A Sorte é 10 (neutra).</p>'],
];

